from __future__ import unicode_literals

import unittest
from functools import partial

from ute_common_util.test.temp import path_to_resource, path_to_temp_file

from ute_common_config_files.raml.xml import Xml
from ute_common_config_files.scfc.exceptions import NoSuchParameter, ExactlyOneManagedObjectExpected


path_to_resource = partial(path_to_resource, __name__)


class TestXml(unittest.TestCase):

    @path_to_temp_file
    @path_to_resource('resources/scfc/empty.xml')
    def test_save(self, scfc_path, tmp_path):
        Xml(scfc_path).save(tmp_path)
        self.assertEqual(self._get_content(scfc_path), self._get_content(tmp_path))

    def _get_content(self, path):
        with open(path) as f:
            return f.read()

    @path_to_resource('resources/scfc/empty_managed_object.xml')
    def test_raise_on_node_not_found(self, scfc_path):
        xml = Xml(scfc_path)
        with self.assertRaises(NoSuchParameter) as context:
            xml._raise_on_node_not_found(NoSuchParameter,
                                         starting_node=xml._find_node('{*}cmData'),
                                         path='{*}p[@name="{param_name}"]',
                                         param_name='param',
                                         some_other_param='xxx')
        message = str(context.exception)
        self.assertTrue(message.startswith('Could not find required node in the XML. Additional info:\n'))
        self.assertTrue('source: ' in message)
        self.assertTrue('starting node: <cmData xmlns="raml21.xsd" type="actual">' in message)
        self.assertTrue('path: {*}p[@name="param"]' in message)
        self.assertTrue('param_name: param' in message)
        self.assertTrue('some_other_param: xxx' in message)

    @path_to_resource('resources/scfc/3_empty_managed_objects.xml')
    def test_raise_on_unexpected_multiple_nodes(self, scfc_path):
        xml = Xml(scfc_path)
        with self.assertRaises(ExactlyOneManagedObjectExpected) as context:
            xml._raise_on_unexpected_multiple_nodes(ExactlyOneManagedObjectExpected,
                                                    starting_node=xml._find_node('{*}cmData'),
                                                    found_nodes=xml._find_all_nodes('{*}cmData/{*}managedObject[@class="LCELL"]'),
                                                    path='{*}managedObject[@class="{managed_object_class}"]',
                                                    managed_object_class='LCELL')
        message = str(context.exception)
        self.assertTrue(message.startswith('Found more than one matching node when only one was expected. Additional info:\n'))
        self.assertTrue('source: ' in message)
        self.assertTrue('starting node: <cmData xmlns="raml21.xsd" type="actual">' in message)
        self.assertTrue('path: {*}managedObject[@class="LCELL"]' in message)
        self.assertTrue('managed_object_class: LCELL' in message)
        self.assertTrue('found node #1: <managedObject xmlns="raml21.xsd" class="LCELL" distName="MRBTS-1/BTSSCL-1/LCELL-2"' in message)
        self.assertTrue('found node #2: <managedObject xmlns="raml21.xsd" class="LCELL" distName="MRBTS-1/BTSSCL-1/LCELL-3"' in message)
        self.assertTrue('found node #3: <managedObject xmlns="raml21.xsd" class="LCELL" distName="MRBTS-1/BTSSCL-1/LCELL-1"' in message)

    @path_to_resource('resources/scfc/self_closed.xml')
    def test_replace_self_closing_tags(self, scfc_path):
        xml = Xml(scfc_path)
        node = xml._find_node('{*}cmData/{*}managedObject')
        self.assertEqual(node.text, None)

        xml._replace_self_closing_tags(xml.xml)
        node = xml._find_node('{*}cmData/{*}managedObject')
        self.assertEqual(node.text, "")
